use std::fs
use std::env
use std::process

fn emit(text: string, number: bool, counter: int) -> int {
    if !number {
        print(text)
        return counter
    }
    let mut parts: Vec<string> = text.split("\n").collect()
    if parts.len() > 0 && parts[parts.len() - 1] == "" {
        parts.pop()
    }
    let mut c: int = counter
    for p in parts {
        c += 1
        println("${c:>6}\t${p}")
    }
    c
}

fn main() {
    let mut number = false
    let mut files: Vec<string> = []
    for a in env::args().skip(1) {
        if a == "-n" {
            number = true
        } else {
            files.push(a)
        }
    }
    let mut counter: int = 0
    let mut failed = false
    if files.len() == 0 {
        let text = fs::read_to_string("/dev/stdin").unwrap_or("")
        counter = emit(text, number, counter)
    } else {
        for f in files {
            match fs::read_to_string(f) {
                Ok(text) => {
                    counter = emit(text, number, counter)
                }
                Err(_) => {
                    println("cat: ${f}: No such file")
                    failed = true
                }
            }
        }
    }
    if failed {
        process::exit(1)
    }
}
